#!/bin/zsh
# lan-inventory.zsh v1 - list recent neighbours from the ARP cache as CSV
out=${1:-inventory.csv}
print "ip,mac,name,iface" > $out
arp -a | awk '
  $4 == "(incomplete)" || $4 == "ff:ff:ff:ff:ff:ff" { next }
  {
    ip = $2; gsub(/[()]/, "", ip)
    n = split($4, o, ":"); mac = ""
    for (i = 1; i <= n; i++) {
      h = o[i]; if (length(h) == 1) h = "0" h
      mac = mac (i > 1 ? ":" : "") tolower(h)
    }
    printf "%s,%s,%s,%s\n", ip, mac, $1, $6
  }' | sort -t. -k4 -n >> $out
print "wrote $(( $(wc -l < $out) - 1 )) hosts to $out"
